style.css:
@-moz-document domain("youtube.com") {
/* Main Dropdown Container - Tighter width and solid dark theme */
    ytd-multi-page-menu-renderer {
        background: #1f1f1f !important;
        border: 1px solid #2d2d2d !important;
        border-radius: 8px !important;
        box-shadow: 0 4px 20px rgba(0, 0, 0, 0.6) !important;
        max-width: 250px !important; 
        overflow: hidden !important;
    }

    /* Header Section - Clean, minimal vertical space */
    ytd-active-account-header-renderer {
        background: transparent !important;
        padding: 12px 14px 10px 14px !important;
        border-bottom: 1px solid #2d2d2d !important;
    }

    /* Hide the redundant blue "View your channel" link entirely */
    #view-channel-link,
    ytd-button-renderer#view-channel {
        display: none !important;
    }

    /* Make the Username text permanently Blue to act as the primary channel link */
    #account-name {
        font-family: Roboto, Arial, sans-serif !important;
        font-weight: 700 !important;
        font-size: 15px !important;
        color: #0091ff !important; /* Matches the vibrant blue link color in your concept */
        cursor: pointer !important;
    }
    
    #account-name:hover {
        text-decoration: underline !important;
    }

    /* Handle text underneath username */
    #channel-handle {
        color: #aaaaaa !important;
        font-size: 12px !important;
        margin-top: 2px !important;
    }

    /* Ultra-compact Menu Items */
    ytd-compact-link-renderer {
        padding: 0px !important;
        margin: 0px !important;
        min-height: 34px !important; /* Forces the super tight vertical layout */
    }

    ytd-compact-link-renderer:hover {
        background-color: #2a2a2a !important;
    }

    /* Text & Icon alignment inside rows */
    ytd-compact-link-renderer #label {
        font-size: 13.5px !important;
        color: #e1e1e1 !important;
        font-weight: 400 !important;
        white-space: nowrap !important;
        overflow: hidden !important;
        text-overflow: ellipsis !important; /* Matches the text truncations like "Device the..." */
    }

    ytd-compact-link-renderer yt-icon {
        color: #cccccc !important;
        transform: scale(0.85) !important; /* Slightly smaller icons for tight layout */
    }

    /* Clean, thin section dividers */
    ytd-multi-page-menu-renderer yt-horizontal-list-renderer,
    div.style-scope.ytd-multi-page-menu-renderer:not(:last-child) {
        border-bottom: 1px solid #2d2d2d !important;
        margin: 2px 0 !important;
    }

    /* Right chevron icons (>) */
    ytd-compact-link-renderer .right-icon {
        color: #aaaaaa !important;
        transform: scale(0.8) !important;
    }
}
